def candidates_all(grid):
    grid=[list(row) for row in grid]
    p=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==8]
    r0,r1=min(r for r,c in p),max(r for r,c in p);c0,c1=min(c for r,c in p),max(c for r,c in p)
    h,w=r1-r0+1,c1-c0+1; H,W=len(grid),len(grid[0]); out={}
    # reflections across central row/col (sum 31)
    for name,func in [('vflip',lambda r,c:(31-r,c)),('hflip',lambda r,c:(r,31-c)),('rotate',lambda r,c:(31-r,31-c)),('diag',lambda r,c:(c,r)),('antidiag',lambda r,c:(31-c,31-r))]:
        pts=[[func(r,c) for c in range(c0,c1+1)] for r in range(r0,r1+1)]
        if all(0<=rr<H and 0<=cc<W for row in pts for rr,cc in row):
            out[name]=[[grid[func(r0+i,c0+j)[0]][func(r0+i,c0+j)[1]] for j in range(w)] for i in range(h)]
    return out
